  function recordKey(payload){return /^(?:submitAttempt|submitListening|submitFighterListening)$/.test(payload.action||'')&&typeof payload.submissionId==='string'?payload.submissionId:null;}
  function validRecord(r){return r&&r.version===2&&r.payload&&recordKey(r.payload)===r.submissionId&&r.canonical===stable(r.payload)&&['pending','confirmed','blocked'].includes(r.status)&&Number.isFinite(r.revision);}
