  function merge(record){if(!validRecord(record))return;sanitizeReceipt(record);const prior=records.get(record.submissionId);if(prior&&prior.canonical!==record.canonical)return;if(prior&&prior.status==='confirmed'&&record.status!=='confirmed')return;if(!prior||record.status==='confirmed'||record.revision>prior.revision)records.set(record.submissionId,record);}
  function openDatabase(){return new Promise(resolve=>{let settled=false,request;const finish=value=>{if(!settled){settled=true;clearTimeout(timer);resolve(value)}};const timer=setTimeout(()=>finish(null),2000);try{request=root.indexedDB.open('mtt-confirmed-submissions',1);request.onupgradeneeded=()=>request.result.createObjectStore('attempts',{keyPath:'submissionId'});request.onerror=()=>finish(null);request.onblocked=()=>finish(null);request.onsuccess=()=>{if(settled){request.result.close();return;}finish(request.result);};}catch(_){finish(null);}});}
  function database(mode,action){return new Promise((resolve,reject)=>{if(!db)return reject(Error('Storage unavailable'));let tx,request;const timer=setTimeout(()=>{try{tx.abort()}catch(_){}reject(Error('Storage timed out'))},2500);try{tx=db.transaction('attempts',mode);request=action(tx.objectStore('attempts'));tx.oncomplete=()=>{clearTimeout(timer);resolve(request&&request.result)};tx.onerror=tx.onabort=()=>{clearTimeout(timer);reject(tx.error||Error('Storage failed'))};}catch(e){clearTimeout(timer);reject(e);}});}
