    try{preserveReceipt(record,JSON.parse(root.localStorage.getItem(prefix+record.submissionId)));root.localStorage.setItem(prefix+record.submissionId,JSON.stringify(record));saved=true;}catch(e){if(e.code==='SUBMISSION_PAYLOAD_CHANGED')throw e;}
