  function start(record){if(inflight.has(record.submissionId))return inflight.get(record.submissionId);const promise=(async()=>{try{await persist(record);notify(record);if(record.status==='confirmed')return clone(record.result);const result=await withRetries(record.payload);record.status='confirmed';record.result=clone(result);record.error=null;record.updatedAt=Date.now();await persist(record);notify(record);return clone(record.result);}catch(e){preserveReceipt(record,records.get(record.submissionId));if(record.status==='confirmed')return clone(validateReceipt(record.payload,record.result));if(e.code==='SUBMISSION_PAYLOAD_CHANGED')throw e;record.attempts=(record.attempts||0)+1;record.status=retryable(e)?'pending':'blocked';record.error={code:e.code||'TRANSPORT_ERROR',message:e.message};record.updatedAt=Date.now();record.nextRetryAt=Date.now()+Math.min(120000,4000*Math.pow(2,Math.min(record.attempts,5)))+Math.random()*2000;await persist(record);notify(record);if(record.status==='confirmed')return clone(record.result);throw e;}finally{inflight.delete(record.submissionId);schedule();}})();inflight.set(record.submissionId,promise);return promise;}
  function schedule(delay){if(wakeTimer)clearTimeout(wakeTimer);const pending=Array.from(records.values()).filter(r=>r.status==='pending'&&!inflight.has(r.submissionId));if(!pending.length)return;const wait=delay===undefined?Math.max(100,Math.min(...pending.map(r=>(r.nextRetryAt||0)-Date.now()))):delay;wakeTimer=setTimeout(()=>{wakeTimer=null;if(root.navigator&&root.navigator.onLine===false){schedule(15000);return;}const next=Array.from(records.values()).find(r=>r.status==='pending'&&!inflight.has(r.submissionId)&&(r.nextRetryAt||0)<=Date.now());if(next)start(next).catch(()=>{});else schedule();},wait);}
